// Actual rendered QML/production engine, synthetic filesystem only; no live Steam.
inline int candidate19Checks(QQuickWindow *window,Bridge &bridge){
 int failures=0;auto verify=[&](bool ok,const char*name){std::cout<<(ok?"PASS ":"FAIL ")<<name<<std::endl;if(!ok)++failures;};
 auto home=qEnvironmentVariable("HOME");if(!home.contains("c19-lifecycle-fixture")){std::cerr<<"Refuse non-fixture HOME";return 47;}
 auto engine=[](const QString&a,QVariantMap args=QVariantMap{}){wow_reset_cancel();args["action"]=a;auto bytes=QJsonDocument::fromVariant(args).toJson(QJsonDocument::Compact);char*p=wow_request(bytes.constData());auto out=QJsonDocument::fromJson(p).object().toVariantMap();wow_free(p);return out;};
 auto put=[](const QString&path,const QByteArray&bytes){QDir().mkpath(QFileInfo(path).absolutePath());QFile f(path);return f.open(QIODevice::WriteOnly)&&f.write(bytes)==bytes.size();};
 auto read=[](const QString&path){QFile f(path);f.open(QIODevice::ReadOnly);return f.readAll();};
 const auto steam=home+"/.local/share/Steam",data=home+"/.local/share/wow-steamos-rust";
 put(steam+"/userdata/123/config/shortcuts.vdf",QByteArray("\0shortcuts\0\10\10",13));put(steam+"/config/config.vdf","\"InstallConfigStore\" { \"Software\" { \"Valve\" { \"Steam\" { \"CompatToolMapping\" {} } } } }");
 put(steam+"/steamapps/common/Proton 11/proton","fixture");put(steam+"/steamapps/common/Proton 11/toolmanifest.vdf","\"manifest\" { \"commandline\" \"/proton %verb%\" }");put(steam+"/steamapps/common/Proton 11/version","1752000000 proton-11.0-1");put(steam+"/steamapps/appmanifest_4628710.acf","\"AppState\" { \"appid\" \"4628710\" \"StateFlags\" \"4\" \"SizeOnDisk\" \"1\" \"installdir\" \"Proton 11\" }");put(steam+"/steamapps/common/Proton 11/files/bin/wine","fixture");put(steam+"/steamapps/common/Proton 11/files/bin/wineserver","fixture");
 auto install=[&](){auto response=engine("review_setup",{{"steam",steam},{"user","123"},{"proton","proton_11"},{"location",home},{"editions",QStringList{"era"}}});verify(response["ok"].toBool(),"production setup fixture review");auto plan=QJsonDocument::fromJson(read(data+"/review.json")).object().toVariantMap();auto i=plan["installation"].toMap();QByteArray pe(2048,'\0');pe[0]='M';pe[1]='Z';pe[0x3c]=char(0x80);pe.replace(0x80,4,QByteArray("PE\0\0",4));pe[0x84]=char(0x64);pe[0x85]=char(0x86);pe[0x98]=char(0x0b);pe[0x99]=char(0x02);put(i["root"].toString()+"/Battle.net-Setup.exe",pe);verify(engine("apply",{{"token",response["data"].toMap()["token"]}})["ok"].toBool(),"production setup fixture apply");put(i["prefix"].toString()+"/pfx/drive_c/Program Files (x86)/Battle.net/Battle.net.exe","MZ");put(i["prefix"].toString()+"/pfx/drive_c/Program Files (x86)/Steam/steamclient.dll","MZ");put(i["root"].toString()+"/games/World of Warcraft/_classic_era_/WowClassic.exe","MZ");return i;};
 auto remove=[&](const QVariantMap&i){auto response=engine("review_clean",{{"id",i["id"]},{"complete_owned",true},{"keep_settings",false}});verify(response["ok"].toBool(),"production owned-removal fixture review");auto applied=engine("apply",{{"token",response["data"].toMap()["token"]},{"confirmation","REMOVE THIS COPY"}});verify(applied["ok"].toBool()&&!QFileInfo::exists(i["root"].toString()),"production owned-removal deletes only fixture root");};
 auto refresh=[&](){auto response=engine("scan");verify(response["ok"].toBool(),"production discovery refresh");auto d=response["data"].toMap();window->setProperty("scan",d["scan"]);QMetaObject::invokeMethod(window,"refreshSession",Q_ARG(QVariant,d["session"]));QTest::qWait(60);};
 int setupReviews=0;bridge.setSelfCheckResponder([&](const QString&a,const QVariantMap&v){if(a=="review_setup")++setupReviews;return engine(a,v);});
 auto activate=[&](const char*name){auto*i=window->findChild<QQuickItem*>(name);if(!i||!diagnosticWait("lifecycle control enabled",[&]{return i->isVisible()&&i->isEnabled();}))return false;i->forceActiveFocus();QTest::qWait(70);QTest::keyClick(window,Qt::Key_Space);QTest::qWait(100);return true;};
 window->requestActivate();if(!diagnosticWait("lifecycle window active",[&]{return QGuiApplication::focusWindow()==window;}))return 33;
 auto first=install();window->setProperty("selectionInitialized",false);window->setProperty("selectedId",QString());window->setProperty("selectionRequired",false);refresh();verify(window->property("selectedId")==first["id"],"initial current fixture selected normally");remove(first);refresh();verify(window->property("selectedId").toString().isEmpty()&&window->property("selectionRequired").toBool()&&window->property("page")=="home","actual last-removal refresh recreates original safety-latch state");
 activate("homeContinue");verify(window->property("page")=="setup"&&!window->property("selectionRequired").toBool()&&!window->property("reinstallMode").toBool()&&window->property("selectedId").toString().isEmpty(),"explicit Home Install after last removal reaches fresh choices without stale target");
 QMetaObject::invokeMethod(window,"toggleEdition",Q_ARG(QVariant,QVariant("era")),Q_ARG(QVariant,QVariant(true)));activate("setupReview");verify(window->property("page")=="review"&&setupReviews==1,"actual GUI Continue reaches production fresh-setup review");auto newPlan=QJsonDocument::fromJson(read(data+"/review.json")).object().toVariantMap();verify(newPlan["kind"]=="setup"&&newPlan["remove"].toList().isEmpty()&&newPlan["installation"].toMap()["id"]!=first["id"]&&!QFileInfo::exists(newPlan["installation"].toMap()["root"].toString()),"new review has new identity, no deletion and no premature install writes");
 QMetaObject::invokeMethod(window,"returnHome");auto removed=install(),remaining=install();engine("select_installation",{{"id",removed["id"]}});window->setProperty("selectionInitialized",false);window->setProperty("selectedId",QString());window->setProperty("selectionRequired",false);refresh();remove(removed);refresh();verify(window->property("selectedId").toString().isEmpty()&&window->property("selectionRequired").toBool(),"disappeared selection never switches to remaining working copy");
 auto stateBefore=read(data+"/state.json"),shortcutsBefore=read(steam+"/userdata/123/config/shortcuts.vdf");activate("homeContinue");verify(window->property("page")=="home"&&window->property("selectedId").toString().isEmpty()&&window->property("errorText").toString().contains("Choose an installation")&&read(data+"/state.json")==stateBefore&&read(steam+"/userdata/123/config/shortcuts.vdf")==shortcutsBefore,"Home remains guarded with another installation; state and shortcuts unchanged");
 const auto root=remaining["root"].toString();verify(QDir().rename(root,root+"-offline"),"simulate unavailable remaining fixture without deletion");refresh();window->setProperty("errorText",QString());activate("homeContinue");verify(window->property("page")=="home"&&window->property("selectionRequired").toBool()&&window->property("selectedId").toString().isEmpty(),"unavailable remaining installation does not masquerade as empty state");verify(QDir().rename(root+"-offline",root),"restore unavailable fixture");
 engine("select_installation",{{"id",remaining["id"]}});window->setProperty("selectionInitialized",false);window->setProperty("selectedId",QString());window->setProperty("selectionRequired",false);refresh();activate("homeContinue");verify(window->property("page")=="games"&&window->property("selectedId")==remaining["id"],"valid explicitly selected installation still opens normal setup continuation");bridge.setSelfCheckResponder({});return failures?48:0;
}
